'use strict';
const fonts=new Map();let fontDatabase=null;let fontBusy=false;
function applyReading(){const n=Number(state.fontSize);state.fontSize=Number.isFinite(n)&&n>=12&&n<=36?n:18;document.documentElement.style.setProperty('--question-size',state.fontSize+'px');$('#fontSize').value=state.fontSize;$('#fontSizeValue').value=state.fontSize+' px';const builtins={serif:'Georgia,serif',sans:'Arial,Helvetica,sans-serif',mono:'ui-monospace,monospace'};const selected=state.readingFont||'default';const custom=fonts.get(selected);const family=custom?'"'+custom.family+'"':builtins[selected];document.body.classList.toggle('custom-typography',!!family);if(family)document.documentElement.style.setProperty('--reading-font',family);else document.documentElement.style.removeProperty('--reading-font');$('#fontSelect').value=custom||builtins[selected]?selected:'default'}
function applyBorder(){const choices=['rainbow','black','blue','green','red','custom'];if(!choices.includes(state.borderDesign))state.borderDesign='rainbow';if(!/^#[0-9a-f]{6}$/i.test(state.borderColor||''))state.borderColor='#7c3aed';document.body.dataset.border=state.borderDesign;document.body.style.setProperty('--dash-color',state.borderDesign==='custom'?state.borderColor:({black:document.body.classList.contains('dark')?'#d9dce3':'#171717',blue:'#397bc9',green:'#32835d',red:'#ca515b'}[state.borderDesign]||'#171717'));$('#borderDesign').value=state.borderDesign;$('#borderColor').value=state.borderColor;$('#customBorderRow').hidden=state.borderDesign!=='custom'}
$('#borderDesign').onchange=()=>{state.borderDesign=$('#borderDesign').value;applyBorder();persist()};$('#borderColor').oninput=()=>{state.borderColor=$('#borderColor').value;applyBorder();persist()};new MutationObserver(applyBorder).observe(document.body,{attributes:true,attributeFilter:['class']});
$('#fontSize').oninput=()=>{state.fontSize=Number($('#fontSize').value);applyReading();persist()};$('#fontSelect').onchange=()=>{state.readingFont=$('#fontSelect').value;applyReading();persist()};$('#resetTypography').onclick=()=>{state.readingFont='default';state.fontSize=18;applyReading();persist();$('#fontStatus').textContent='Default font and 18 px question text restored.'};
function database(){return new Promise((resolve,reject)=>{const request=indexedDB.open('sat-room-fonts-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('fonts',{keyPath:'id'});request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>db.close();resolve(db)};request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('Font storage is busy. Close other study tabs and retry.'))})}
function fontStore(mode,action){return new Promise((resolve,reject)=>{const tx=fontDatabase.transaction('fonts',mode);const request=action(tx.objectStore('fonts'));let result;request.onsuccess=()=>{result=request.result};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Storage operation cancelled'))})}
async function loadFont(record){const family='StudyFont_'+record.id.replace(/[^a-zA-Z0-9]/g,'');const face=await new FontFace(family,record.bytes).load();document.fonts.add(face);fonts.set(record.id,{...record,family,face})}
function renderFonts(){const select=$('#fontSelect');select.querySelectorAll('[data-custom-font]').forEach(o=>o.remove());const list=$('#customFontList');list.replaceChildren();for(const [id,font]of fonts){const option=document.createElement('option');option.value=id;option.textContent=font.name+' (custom)';option.dataset.customFont='true';select.append(option);const row=document.createElement('div');row.className='custom-font-row';const label=document.createElement('span');label.textContent=font.name;const remove=document.createElement('button');remove.type='button';remove.textContent='Delete';remove.setAttribute('aria-label','Delete custom font '+font.name);remove.onclick=async()=>{if(fontBusy)return;if(!confirm('Delete custom font “'+font.name+'” from this browser?'))return;fontBusy=true;remove.disabled=true;try{await fontStore('readwrite',store=>store.delete(id));document.fonts.delete(font.face);fonts.delete(id);if(state.readingFont===id)state.readingFont='default';renderFonts();applyReading();persist();$('#fontStatus').textContent='Custom font deleted.'}catch{$('#fontStatus').textContent='Could not delete the font. Try again.'}finally{fontBusy=false;remove.disabled=false}};row.append(label,remove);list.append(row)}}
$('#fontUpload').onchange=async()=>{const input=$('#fontUpload'),file=input.files?.[0];if(!file)return;if(fontBusy){input.value='';return}if(!fontDatabase){$('#fontStatus').textContent='Font storage is unavailable. Allow browser storage, then reload.';input.value='';return}if(!/\.(woff2?|ttf|otf)$/i.test(file.name)||file.size>10*1024*1024||!file.size){$('#fontStatus').textContent='Choose a valid WOFF2, WOFF, TTF, or OTF font up to 10 MB.';input.value='';return}fontBusy=true;input.disabled=true;$('#fontStatus').textContent='Loading font…';let record;try{record={id:'font-'+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),name:file.name,bytes:await file.arrayBuffer()};await loadFont(record);await fontStore('readwrite',store=>store.put(record));state.readingFont=record.id;renderFonts();applyReading();persist();$('#fontStatus').textContent='Font saved on this browser and selected.'}catch{if(record&&fonts.has(record.id)){document.fonts.delete(fonts.get(record.id).face);fonts.delete(record.id)}$('#fontStatus').textContent='This font could not be loaded or saved. Try another font or free browser storage.'}finally{fontBusy=false;input.disabled=false;input.value=''}};
async function initFonts(){try{fontDatabase=await database();const records=await fontStore('readonly',store=>store.getAll());let failed=0;for(const record of records){try{await loadFont(record)}catch{failed++;const row=document.createElement('div');row.className='custom-font-row';const text=document.createElement('span');text.textContent=record.name+' (unavailable)';const remove=document.createElement('button');remove.textContent='Delete';remove.onclick=async()=>{if(!confirm('Delete this unavailable custom font from this browser?'))return;try{await fontStore('readwrite',s=>s.delete(record.id));row.remove()}catch{$('#fontStatus').textContent='Could not delete font. Reload and retry.'}};row.append(text,remove);$('#customFontList').append(row)}}const failedRows=[...$('#customFontList').children];renderFonts();$('#customFontList').append(...failedRows);applyReading();if(failed)$('#fontStatus').textContent='Some saved fonts could not load. You can delete them or upload another copy.'}catch{$('#fontStatus').textContent='Custom font storage is unavailable. Built-in fonts and size controls still work.'}}
$('#clearDataBtn').onclick=async()=>{if(fontBusy){$('#fontStatus').textContent='Wait for the font operation to finish, then retry.';return}if(!confirm('Delete all answers, settings, session data, and custom fonts from this browser?'))return;try{if(fontDatabase)await fontStore('readwrite',store=>store.clear());else{const db=await database();fontDatabase=db;await fontStore('readwrite',store=>store.clear())}localStorage.removeItem('sat-room-v1');for(const font of fonts.values())document.fonts.delete(font.face);location.replace(location.pathname)}catch{$('#fontStatus').textContent='Could not clear all data. Close other study tabs and retry, or clear this site’s storage in your browser.'}};
$('#noticeBtn').onclick=()=>openDialog('#noticeDialog');$('#dismissNotice').onclick=()=>{state.noticeVersion='2026-10-29-fonts';persist();$('#noticeDialog').close()};$('#noticeDialog').addEventListener('close',()=>{state.noticeVersion='2026-10-29-fonts';persist()});applyBorder();applyReading();initFonts();if(state.noticeVersion!=='2026-10-29-fonts')openDialog('#noticeDialog');
